#include "test_cpu_freq.h"
#include "../../../../../tf_common/tf_test_results.h"
#include "../../../../../tf_common/tf_cpu.h"


// Flag to ensure we only report the test result at most once
static asn1SccT_Boolean bResultReported = false;


// Constructor
void test_cpu_freq_startup(void)
{
    // Register the test that this TASTE Function will submit a result for
    testresult_register_test(TF_TEST_ID__TestCpuFreqCustom);
}


// Handler for cyclic IF: Validates that CPU is NOT running at 100 MHz and reports the result
void test_cpu_freq_PI_trigger_check(void)
{
    // Only do this once
    if (bResultReported) {
        return;
    }

    // Determine if the processor clock frequency config is NOT matching that for 100 MHz
    if (!is_processor_clock_100mhz()) {
        testresult_report_pass(TF_TEST_ID__TestCpuFreqCustom);
    } else {
        testresult_report_fail(TF_TEST_ID__TestCpuFreqCustom, "Processor clock is running at 100 MHz, despite compiler flag requesting 75 MHz");
    }

    // Report that we already did this
    bResultReported = true;
}


